    animated: `<div class="vis-wrap" id="alg-a"><style>#alg-a .vsteps{display:flex;gap:6px;flex-wrap:wrap;margin-bottom:12px}#alg-a .vsp{padding:7px 14px;border-radius:999px;border:1px solid #ddd;font-size:13px;cursor:pointer;background:#f9f9f9;color:#555}#alg-a .vsp.on{background:#ef8354;color:#fff;border-color:#ef8354}#alg-a .vsc{background:#fdf6ee;border-radius:12px;padding:18px;text-align:center;min-height:160px;display:flex;align-items:center;justify-content:center}#alg-a .vcp{font-size:13px;color:#666;text-align:center;margin-top:10px;min-height:36px;line-height:1.6}#alg-a .veq{font-size:22px;font-weight:700;color:#ef8354;margin-top:8px;text-align:center}</style><div class="vsteps"><button class="vsp on" onclick="algA(0)">① Scale</button><button class="vsp" onclick="algA(1)">② Mystery</button><button class="vsp" onclick="algA(2)">③ Undo</button><button class="vsp" onclick="algA(3)">④ Answer</button></div><div class="vsc"><svg id="alg-svg" width="380" height="140" viewBox="0 0 380 140"></svg></div><div class="vcp" id="alg-cp">A balanced scale — both sides always equal. This is every equation.</div><div class="veq" id="alg-eq">12 = 12</div></div><script>(function(){var caps=["A balanced scale — both sides always equal. This is every equation.","We hide x in an orange box, add 5 blocks. Right side still shows 12.","Undo the +5: subtract 5 from BOTH sides. Balance stays!","Box opens! x=7. Check: 7+5=12 ✓ Always check your answer."];var eqs=["12 = 12","x + 5 = 12","x + 5 − 5 = 12 − 5","x = 7 ✓"];function draw(step){var s=document.getElementById("alg-svg");var cx=190,py=30,arm=130,panY=90,pw=75,ph=28,lx=cx-arm,rx=cx+arm;var leftItems=[["x","#ef8354"],["5","#5c8acb"],["5","#5c8acb"],["5","#5c8acb"],["5","#5c8acb"],["5","#5c8acb"]];var rightItems=[["12","#3d9970"]];if(step===0){leftItems=[["12","#5c8acb"]];} if(step===2){leftItems=[["x","#ef8354"]];rightItems=[["7","#3d9970"]];} if(step===3){leftItems=[["7","#3d9970"]];rightItems=[["7","#3d9970"]];}var out="<line x1='"+cx+"' y1='8' x2='"+cx+"' y2='"+py+"' stroke='#999' stroke-width='3'/><circle cx='"+cx+"' cy='"+py+"' r='4' fill='#888'/><line x1='"+lx+"' y1='"+py+"' x2='"+rx+"' y2='"+py+"' stroke='#777' stroke-width='2'/><line x1='"+lx+"' y1='"+py+"' x2='"+lx+"' y2='"+panY+"' stroke='#aaa' stroke-width='1.5'/><line x1='"+rx+"' y1='"+py+"' x2='"+rx+"' y2='"+panY+"' stroke='#aaa' stroke-width='1.5'/><rect x='"+(lx-pw/2)+"' y='"+panY+"' width='"+pw+"' height='"+ph+"' rx='5' fill='#fde8d8'/><rect x='"+(rx-pw/2)+"' y='"+panY+"' width='"+pw+"' height='"+ph+"' rx='5' fill='#e3f5ed'/><text x='"+lx+"' y='"+(panY+ph/2+5)+"' text-anchor='middle' font-size='14' font-weight='700' fill='#8b3010'>"+leftItems.map(function(i){return i[0];}).join("+")+"</text><text x='"+rx+"' y='"+(panY+ph/2+5)+"' text-anchor='middle' font-size='14' font-weight='700' fill='#1e5c3e'>"+rightItems[0][0]+"</text><text x='"+lx+"' y='"+(panY+ph+16)+"' text-anchor='middle' font-size='11' fill='#999'>Left</text><text x='"+rx+"' y='"+(panY+ph+16)+"' text-anchor='middle' font-size='11' fill='#999'>Right</text>";s.innerHTML=out;}function algA(i){document.querySelectorAll("#alg-a .vsp").forEach(function(b,j){b.classList.toggle("on",j===i);});document.getElementById("alg-cp").textContent=caps[i];document.getElementById("alg-eq").textContent=eqs[i];draw(i);}window.algA=algA;algA(0);})();</script>`,
    interactive: `<div class="vis-wrap" id="alg-i"><style>#alg-i .vc{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:8px}#alg-i .vc label{font-size:13px;color:#666;min-width:70px}#alg-i .vc input[type=range]{flex:1}#alg-i .vv{font-size:16px;font-weight:700;color:#ef8354;min-width:24px}#alg-i .eb{background:#fff8f0;border:1.5px solid #f4a261;border-radius:10px;padding:12px;margin:10px 0;text-align:center}#alg-i .em{font-size:20px;font-weight:700;color:#ef8354}#alg-i .es{font-size:13px;color:#888;margin-top:4px;line-height:1.6}#alg-i .eo{font-size:13px;color:#3d9970;font-weight:600;margin-top:4px}</style><p style="font-size:13px;color:#666;margin-bottom:10px">Set x and the number added. Watch the equation form live.</p><div class="vc"><label>Mystery x:</label><input type="range" id="ai-x" min="1" max="15" value="7" step="1" oninput="aiDraw()"><span class="vv" id="ai-xv">7</span></div><div class="vc"><label>Add this:</label><input type="range" id="ai-a" min="1" max="15" value="5" step="1" oninput="aiDraw()"><span class="vv" id="ai-av">5</span></div><div class="eb"><div class="em" id="ai-e1">x + 5 = 12</div><div class="es" id="ai-e2">Subtract 5 from both sides to get x = 7</div><div class="eo" id="ai-eo">Check: 7 + 5 = 12</div></div></div><script>(function(){function aiDraw(){var x=parseInt(document.getElementById("ai-x").value);var a=parseInt(document.getElementById("ai-a").value);var rhs=x+a;document.getElementById("ai-xv").textContent=x;document.getElementById("ai-av").textContent=a;document.getElementById("ai-e1").textContent="x + "+a+" = "+rhs;document.getElementById("ai-e2").textContent="Subtract "+a+" from both sides to get x = "+rhs+" - "+a+" = "+x;document.getElementById("ai-eo").textContent="Check: "+x+" + "+a+" = "+rhs+" \u2713";}window.aiDraw=aiDraw;aiDraw();})();</script>`
