    interactive: `<div class="vis-wrap" id="g7i-i"><style>#g7i-i .vc{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:8px}#g7i-i .vc label{font-size:13px;color:#666;min-width:70px}#g7i-i select,#g7i-i input[type=number]{padding:7px 10px;border-radius:8px;border:1px solid #ddd;font:inherit;font-size:13px}#g7i-i .eb{background:#eaf3fc;border:1.5px solid #4a90d9;border-radius:10px;padding:12px;margin:10px 0;text-align:center}#g7i-i .em{font-size:20px;font-weight:700;color:#4a90d9}#g7i-i .es{font-size:13px;color:#888;margin-top:4px;line-height:1.6}</style><p style="font-size:13px;color:#666;margin-bottom:10px">Pick two integers and an operation. Watch the sign rule apply live.</p><div class="vc"><label>First:</label><input type="number" id="g7ii-a" value="-6" oninput="g7iiDraw()" style="width:65px"><label>Operation:</label><select id="g7ii-op" onchange="g7iiDraw()"><option value="add">+</option><option value="sub">−</option><option value="mul" selected>×</option><option value="div">÷</option></select><label>Second:</label><input type="number" id="g7ii-b" value="-4" oninput="g7iiDraw()" style="width:65px"></div><div class="eb"><div class="em" id="g7ii-e1">-6 × -4 = 24</div><div class="es" id="g7ii-e2">Same signs → positive result</div></div></div><script>(function(){function g7iiDraw(){var a=parseInt(document.getElementById("g7ii-a").value)||0;var b=parseInt(document.getElementById("g7ii-b").value)||0;var op=document.getElementById("g7ii-op").value;var sym={add:"+",sub:"−",mul:"×",div:"÷"}[op];var r;if(op==="add")r=a+b;else if(op==="sub")r=a-b;else if(op==="mul")r=a*b;else r=b!==0?(a/b):NaN;document.getElementById("g7ii-e1").textContent=a+" "+sym+" "+b+" = "+(isNaN(r)?"undefined":r);var msg;if(op==="add"||op==="sub"){msg="Move along the number line: "+(op==="add"?"add moves toward positive":"subtracting a negative flips to addition");}else{var sameSign=(a<0&&b<0)||(a>=0&&b>=0);msg=sameSign?"Same signs → positive result":"Different signs → negative result";}document.getElementById("g7ii-e2").textContent=msg;}window.g7iiDraw=g7iiDraw;g7iiDraw();})();</script>`
